values ('d128f68d-db6a-5f65-a40e-b475438ddd51', 'd6c39c97-71c3-55b3-9c7d-d6820b36524f', $j${"uz":"Uchta guldonda hammasi bo'lib 100 ta gul bor. Ikkinchi guldonda birinchi guldondagidan 2 marta ko'p, uchinchi guldondagidan 15 ta ko'p gul bor. Ikkinchi guldonda nechta gul bor?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"17","ru":"","en":""}},{"id":"B","text":{"uz":"46","ru":"","en":""}},{"id":"C","text":{"uz":"32","ru":"","en":""}},{"id":"D","text":{"uz":"25","ru":"","en":""}}]$j$::jsonb, 'B', $j${"uz":"Birinchida a ta, ikkinchida 2a, uchinchida 2a - 15 ta. a + 2a + 2a - 15 = 100, 5a = 115, a = 23. Ikkinchida 2 · 23 = 46 ta.","ru":"","en":""}$j$::jsonb, 1, 6)
