values ('20497561-8753-5eaa-87e8-23b17ee6aa67', 'd6c39c97-71c3-55b3-9c7d-d6820b36524f', $j${"uz":"Palov tayyorlash uchun guruch va sabzi teng solinadi. Go'sht guruchdan 2 marta kam, yog' guruchdan 4 marta kam, piyoz esa guruchdan 8 marta kam solinadi. Agar 8 kg guruchdan palov tayyorlamoqchi bo'lsak, jami necha kilogramm mahsulot sotib olishimiz kerak?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"24","ru":"","en":""}},{"id":"B","text":{"uz":"22","ru":"","en":""}},{"id":"C","text":{"uz":"23","ru":"","en":""}},{"id":"D","text":{"uz":"15","ru":"","en":""}}]$j$::jsonb, 'C', $j${"uz":"Guruch 8 kg, sabzi 8 kg, go'sht 4 kg, yog' 2 kg, piyoz 1 kg. Jami: 8 + 8 + 4 + 2 + 1 = 23 kg.","ru":"","en":""}$j$::jsonb, 1, 12)
