values ('11915061-0316-510e-8a6f-3604a1df17c4', 'd6c39c97-71c3-55b3-9c7d-d6820b36524f', $j${"uz":"Har yili Ramazon hayitida Solihaning dadasi unga ayiqcha o'yinchog'ini olib kelib beradi. Dadasi unga 1 yoshligida bitta, 2 yoshligida ikkita va hokazo shu tartibda. Har yili olib bergan ayiqchalari soni oldingi yildagidan 1 taga ko'p edi. Soliha 6 yoshligida jami nechta ayiqchaga ega bo'ldi?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"19","ru":"","en":""}},{"id":"B","text":{"uz":"20","ru":"","en":""}},{"id":"C","text":{"uz":"21","ru":"","en":""}},{"id":"D","text":{"uz":"22","ru":"","en":""}}]$j$::jsonb, 'C', $j${"uz":"1 + 2 + 3 + 4 + 5 + 6 = 21 ta.","ru":"","en":""}$j$::jsonb, 1, 13)
