values ('372eb246-ec53-56e5-854d-cdcff3cd0e65', 'd6c39c97-71c3-55b3-9c7d-d6820b36524f', $j${"uz":"Farhodda dunyodagi xohlagan shaharni qidirib topish mumkin bo'lgan xarita bor. Farhod: “Agar menga bitta shaharning nomini aytsangiz, uning qaysi davlatda ekanligini aytishingiz shart emas. Men uni darhol xaritadan topib olaman.” Quyidagi qaysi biri Farhodning gapi xato ekanligini ko'rsatadi?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Ba'zi shaharlarning nomlari bir xil.","ru":"","en":""}},{"id":"B","text":{"uz":"Ba'zi shaharlarning nomlari o'zi joylashgan davlat nomlari bilan bir xil.","ru":"","en":""}},{"id":"C","text":{"uz":"Ba'zi davlatlarda birorta ham shahar yo'q.","ru":"","en":""}},{"id":"D","text":{"uz":"Ba'zi shaharlarning nomlari o'zgargan.","ru":"","en":""}}]$j$::jsonb, 'A', $j${"uz":"Agar turli davlatlarda bir xil nomli shaharlar bo'lsa, davlatni bilmasdan to'g'ri shaharni topib bo'lmaydi.","ru":"","en":""}$j$::jsonb, 1, 15)
