values ('c3bd3873-f2b5-51c9-a145-7aa48a49069f', 'd6c39c97-71c3-55b3-9c7d-d6820b36524f', $j${"uz":"Muattar ustoz: “Mening sinfimda ko'rish qobiliyati pastroq 10 nafar o'quvchi bor. Bugun ertalab sinfimizda 7 nafar o'quvchi ko'zoynak taqib yurgandi. Demak, sinfimizda ba'zilar kontakt linza taqib yurgan bo'lishi kerak.” Muattar ustoz bunday fikrlash orqali qanday xatolikka yo'l qo'ygan bo'lishi mumkin?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"U boshqa sinfdagi o'quvchilarni hisobga olmadi.","ru":"","en":""}},{"id":"B","text":{"uz":"U qaysi o'quvchi kontakt linza taqib yurganini aytmadi.","ru":"","en":""}},{"id":"C","text":{"uz":"Hozirda ko'rish qobiliyati past o'quvchilar kelajakda ko'zoynak taqib yurishga ehtiyojmand bo'lishi mumkin.","ru":"","en":""}},{"id":"D","text":{"uz":"Ba'zi ko'rish qobiliyati past o'quvchilar ko'zoynak ham, kontakt linza ham taqib yurmagan bo'lishi mumkin.","ru":"","en":""}}]$j$::jsonb, 'D', $j${"uz":"10 nafardan 7 tasi ko'zoynak taqqan, qolgan 3 tasi esa hech narsa taqmagan bo'lishi mumkin. Shuning uchun linza taqqanlar bor degan xulosa shart emas.","ru":"","en":""}$j$::jsonb, 1, 16)
