values ('ec5b9651-5c2e-5b4f-99ef-24ab5df35882', 'd6c39c97-71c3-55b3-9c7d-d6820b36524f', $j${"uz":"Avtomobil ijaraga beruvchi: “Biz mashinalarimizga yangi moslama o'rnatamiz. U yo'nalishni o'zbek tilida tushuntirib boradi. Bizning bu loyihamiz, ayniqsa, chet eldan kelgan va shahrimizni bilmaydigan sayyohlar uchun juda foydali bo'ladi.” Yuqoridagi rejada qanday xatolik mavjud?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Shaharga keladigan sayyohlarning aksariyati o'zbek tilini bilmaydi.","ru":"","en":""}},{"id":"B","text":{"uz":"Bu moslamani ko'plab mashinalarga o'rnatish qimmatga tushadi.","ru":"","en":""}},{"id":"C","text":{"uz":"Shaharda qog'oz xaritalar juda arzon.","ru":"","en":""}},{"id":"D","text":{"uz":"Qurilmaning ovozi o'ta baland va bu haydovchilarni chalg'itadi.","ru":"","en":""}}]$j$::jsonb, 'A', $j${"uz":"Moslama o'zbek tilida gapiradi, chet ellik sayyohlar esa o'zbek tilini bilmasligi mumkin. Reja aynan ular uchun foydasiz bo'ladi.","ru":"","en":""}$j$::jsonb, 1, 17)
