values ('b7339186-7dc2-52e2-be1d-983bdbf0bab1', 'd6c39c97-71c3-55b3-9c7d-d6820b36524f', $j${"uz":"Agar shahar ichiga 8 tonnadan og'irroq yuk mashinalarining kirishi cheklansa, yuk mashinalari shaharga kira olmaydi va bu shahardagi transport qatnovini keskin kamaytiradi. Quyidagi qaysi ma'lumot yuqoridagi taklifning samarasiz ekanligini bildiradi?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Shahar tashqarisidagi yo'llarning sifati juda yaxshi.","ru":"","en":""}},{"id":"B","text":{"uz":"Shaharda harakatlanadigan yuk mashinalarining juda ozginasi 8 tonnadan og'irroq.","ru":"","en":""}},{"id":"C","text":{"uz":"Shahar tashqarisida mashina qatnovi juda kam.","ru":"","en":""}},{"id":"D","text":{"uz":"Shaharda yengil mashinalar ko'pincha yuk mashinalar bilan to'qnashib ketadi.","ru":"","en":""}}]$j$::jsonb, 'B', $j${"uz":"Agar 8 tonnadan og'ir yuk mashinalari kam bo'lsa, ularni cheklash qatnovni deyarli kamaytirmaydi.","ru":"","en":""}$j$::jsonb, 1, 18)
