values ('53b0f50b-1f37-5807-b4fe-714c83707ecf', '75ec9466-5285-5de4-8682-c1170588b330', $j${"uz":"Qutida 50 tadan kam pecheniye bor. Pecheniyelar 2, 3 yoki 4 bola o'rtasida teng taqsimlanishi mumkin. Lekin ularni 7 nafar bolaga teng miqdorda bo'lib bo'lmaydi, sababi yana 6 ta pecheniye ortib qoladi. Qutida nechta pecheniye bor?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"12","ru":"","en":""}},{"id":"B","text":{"uz":"24","ru":"","en":""}},{"id":"C","text":{"uz":"48","ru":"","en":""}},{"id":"D","text":{"uz":"30","ru":"","en":""}}]$j$::jsonb, 'C', $j${"uz":"Son 2, 3, 4 ga bo'linadi, demak 12 ga karrali: 12, 24, 36, 48. 7 ga bo'lganda qoldiq 6 bo'ladigani faqat 48 (48 = 6 · 7 + 6).","ru":"","en":""}$j$::jsonb, 1, 13)
