values ('10e5cbf0-af30-5dac-a29f-da5318d2ef76', '75ec9466-5285-5de4-8682-c1170588b330', $j${"uz":"Alida 3 ta kulcha va 8 ta bir xil tanga, Valida 5 ta kulcha va 8 ta bir xil tanga bor. Solida bunday kulchalar yo'q, ammo unda 8 ta bir xil tanga bor. Uchala bola kulchalarni barobar bo'lib yeyishdi. Soli 8 ta tangani ularga “Shirin kulchalar uchun rahmat” deb berdi. Bu tangalarni Ali va Vali qanday bo'lib olishlari kerak?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Ali 3 tanga, Vali 5 tanga","ru":"","en":""}},{"id":"B","text":{"uz":"Ali 2 tanga, Vali 6 tanga","ru":"","en":""}},{"id":"C","text":{"uz":"Ali 5 tanga, Vali 3 tanga","ru":"","en":""}},{"id":"D","text":{"uz":"Ali 1 tanga, Vali 7 tanga","ru":"","en":""}}]$j$::jsonb, 'D', $j${"uz":"Jami 8 ta kulcha, har bola 8/3 kulcha yeydi. Ali Soliga 3 - 8/3 = 1/3, Vali 5 - 8/3 = 7/3 kulcha bergan. Tangalar 1 : 7 nisbatda bo'linadi: Ali 1, Vali 7 tanga.","ru":"","en":""}$j$::jsonb, 1, 14)
