values ('a1cd30ad-eac2-5c31-a9b5-3a9a207380de', '75ec9466-5285-5de4-8682-c1170588b330', $j${"uz":"Diyora va Yunus maktab koridorida turibdi. Diyora: “Hilola menga kurtkasini olib kelishimni iltimos qildi. Lekin men uni topa olmadim. Kurtka moviy rangda va qalpoqli edi.” Yunus: “Mana bu yerda moviy rangli qalpoqli kurtka bor. Bu Hilolaniki bo'lsa kerak.” Yunus bunday fikrlashda qanday xatolikka yo'l qo'ygan bo'lishi mumkin?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Moviy rangdagi qalpoqli kurtkalar bir qancha bo'lishi mumkin.","ru":"","en":""}},{"id":"B","text":{"uz":"Hilola boshqacha kurtkani yoqtirishi mumkin.","ru":"","en":""}},{"id":"C","text":{"uz":"Diyora boshqa birovning kurtkasini qidirayotgan bo'lishi mumkin.","ru":"","en":""}},{"id":"D","text":{"uz":"Kurtka moviy bo'lsa-da, unda qalpoq bo'lmasligi mumkin.","ru":"","en":""}}]$j$::jsonb, 'A', $j${"uz":"Bir xil rang va shakldagi kurtkalar ko'p bo'lishi mumkin, shuning uchun topilgan kurtka aynan Hilolaniki ekani shart emas.","ru":"","en":""}$j$::jsonb, 1, 15)
