values ('6a66a04c-f657-530d-be81-c7dde68fa5a4', '75ec9466-5285-5de4-8682-c1170588b330', $j${"uz":"Farhod: “Pianino imtihonidan o'tish uchun kuniga 15 minutdan haftada to'rt kun shug'ullanish kerak.” Sanjar: “Men har kuni 20 minutdan ko'proq shug'ullandim, shuning uchun imtihondan o'tishimga to'liq aminman.” Sanjar bunday fikrlash orqali qanday xatolikka yo'l qo'ygan bo'lishi mumkin?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Imtihon topshirish, odatda, asabiy bo'ladi.","ru":"","en":""}},{"id":"B","text":{"uz":"Minimum talab qilinadigan darajada shug'ullanish imtihondan o'tishni kafolatlay olmasligi mumkin.","ru":"","en":""}},{"id":"C","text":{"uz":"Cholg'u asbobini yaxshi chalishni o'rganish ko'p yil talab qiladi.","ru":"","en":""}},{"id":"D","text":{"uz":"Yolg'iz shug'ullanish o'qituvchi bilan shug'ullanishdek samarali emas.","ru":"","en":""}}]$j$::jsonb, 'B', $j${"uz":"Farhodning gapida minimal shart aytilgan, u imtihondan o'tishni kafolatlamaydi. Sanjar shartni yetarli deb xato o'ylagan.","ru":"","en":""}$j$::jsonb, 1, 16)
