values ('3712b24a-b3b2-51e9-b8fd-6809b8c16c9f', '75ec9466-5285-5de4-8682-c1170588b330', $j${"uz":"Guru mamlakati neft va gaz konlariga juda boy. Bu konlardan olinadigan energiya Guru aholisining ehtiyojidan ham ortiqcha. Lekin Guru fuqarolari gaz va benzin tanqisligidan aziyat chekadi. Yuqoridagi ziddiyatli holatning sababini tushuntirib beradigan gapni toping.","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Guruda ishlab chiqariladigan neft va gazning katta qismi boshqa mamlakatlarga sotiladi.","ru":"","en":""}},{"id":"B","text":{"uz":"Konlardan yil davomida bir xil miqdorda neft va gaz qazib olinmaydi.","ru":"","en":""}},{"id":"C","text":{"uz":"Guru mamlakatida odamlar elektr jihozlardan juda ko'p foydalanadilar.","ru":"","en":""}},{"id":"D","text":{"uz":"Guru mamlakati quyosh va shamol energiyasini rivojlantirmagan.","ru":"","en":""}}]$j$::jsonb, 'A', $j${"uz":"Agar mahsulotning katta qismi chet elga sotilsa, boy konlarga qaramay ichkarida tanqislik bo'lishi mumkin.","ru":"","en":""}$j$::jsonb, 1, 17)
