values ('b3765442-0f3c-5a39-8178-1c056319312d', '75ec9466-5285-5de4-8682-c1170588b330', $j${"uz":"Ilhom: “Oxirgi 10 yilda kofening zararlari haqida juda ko'p maqolalar yozildi. Buning natijasida shu davrda kofe iste'moli keskin kamaydi.” Quyidagi qaysi gap Ilhomning xulosasi xato ekanligini ko'rsatadi?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Odamlar bugungi kunda 10 yil oldingiga qaraganda kofeni ikki barobar kam iste'mol qilishmoqda.","ru":"","en":""}},{"id":"B","text":{"uz":"Oddiy kofening bahosi pasayganligi tufayli maxsus sifatli kofening savdosi barqaror qoldi.","ru":"","en":""}},{"id":"C","text":{"uz":"So'nggi 10 yil ichida qahva yetishtiradigan mamlakatlarda noodatiy qattiq sovuq tufayli kofe narxi doimiy oshdi.","ru":"","en":""}},{"id":"D","text":{"uz":"So'nggi 10 yil ichida meva sharbatlari va choylarni iste'mol qilish oshdi.","ru":"","en":""}}]$j$::jsonb, 'C', $j${"uz":"Iste'molning kamayishiga boshqa sabab ham bor: narxning doimiy oshishi. Demak, sababi faqat maqolalar degan xulosa noto'g'ri bo'lishi mumkin.","ru":"","en":""}$j$::jsonb, 1, 18)
