values ('b0de1b82-412a-5051-8c40-689274a8073d', '75ec9466-5285-5de4-8682-c1170588b330', $j${"uz":"Husnora: “Nodir bu yil maktabni bitiradi va universitetga hujjat topshiradi. Lekin, afsuski, Nodir matematika va fizika fanlaridan umuman kitoblar o'qimadi va yetarlicha tayyorgarlik ko'rmadi. Shuning uchun men Nodir bu yil universitet imtihonlaridan o'ta oladi deb o'ylamayman.” Quyidagi gaplardan qaysi biri Husnoraning fikrlashidagi xatolikni ko'rsatadi?","ru":"","en":""}$j$::jsonb, $j$[{"id":"A","text":{"uz":"Universitet imtihonlarida matematika va fizika fanlaridan qo'shimcha tarzda ona tili va adabiyot fanidan ham imtihon topshiriladi.","ru":"","en":""}},{"id":"B","text":{"uz":"Nodir hujjat topshirgan universitetning kirish imtihonlarida matematika va fizika fanlari bo'yicha savollar bo'lmaydi.","ru":"","en":""}},{"id":"C","text":{"uz":"Nodirning oxirgi ikki chorakda matematika va fizika fanlari bo'yicha choraklik baholari 3 bo'lgan edi.","ru":"","en":""}},{"id":"D","text":{"uz":"Universitet kirish imtihonlarida tushadigan savollar yildan yilga qiyinlashib bormoqda.","ru":"","en":""}}]$j$::jsonb, 'B', $j${"uz":"Agar imtihonda matematika va fizika bo'lmasa, tayyorgarlikning yo'qligi Husnora o'ylagan natijaga olib kelmaydi.","ru":"","en":""}$j$::jsonb, 1, 19)
